function makeLp(
  name: string,
  headline: string,
  subheadline: string,
  painMap: string[],
  journey: string[],
  primaryCta = 'Testar 5 dias grátis',
): VerticalLpProfile {
  return {
    heroEyebrow: `VendorAI para ${name}`,
    headline,
    subheadline,
    primaryCta,
    secondaryCta: 'Ver demonstração',
    painMap,
    timeline: journey.map(label => ({ label })),
    faq: [
      `O VendorAI funciona para ${name.toLowerCase()}?`,
      'Preciso trocar meus canais atuais?',
      'A IA pode acompanhar oportunidades automaticamente?',
      'Consigo medir qual campanha gerou a venda?',
      'Como funciona o trial de 5 dias?',
    ],
  }
}

function v(input: Omit<MarketingVerticalProfile, 'lp'> & { headline: string; subheadline: string; painMap: string[]; primaryCta?: string }): MarketingVerticalProfile {
  const { headline, subheadline, painMap, primaryCta, ...profile } = input
  return {
    ...profile,
    lp: makeLp(profile.name, headline, subheadline, painMap, profile.journey, primaryCta),
  }
}

