export function getMarketingVerticalById(id: string): MarketingVerticalProfile | undefined {
  return MARKETING_VERTICALS.find(profile => profile.id === id)
}

export function getMarketingVerticalBySlug(slug: string): MarketingVerticalProfile | undefined {
  return MARKETING_VERTICALS.find(profile => profile.slug === slug)
}

export function getMarketingVerticalsByMacrosegment(macrosegment: MarketingMacrosegmentKey): MarketingVerticalProfile[] {
  return MARKETING_VERTICALS.filter(profile => profile.macrosegment === macrosegment)
}

export function resolveMarketingVertical(value?: string | null): MarketingVerticalProfile | undefined {
  const normalized = (value ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim()
  if (!normalized) return undefined
  return MARKETING_VERTICALS.find(profile => {
    const haystack = [profile.id, profile.name, profile.slug, ...profile.googleIntentSeeds]
      .join(' ')
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .toLowerCase()
    return haystack.includes(normalized) || normalized.includes(profile.slug)
  })
}

export function assertOfficialMarketingArchitecture(): true {
  if (MARKETING_MACROSEGMENTS.length !== 6) throw new Error(`Expected 6 macrosegments, got ${MARKETING_MACROSEGMENTS.length}`)
  if (MARKETING_VERTICALS.length !== 50) throw new Error(`Expected 50 verticals, got ${MARKETING_VERTICALS.length}`)
  return true
}
